import '@servicenow/sdk/global'
import { BooleanColumn, IntegerColumn, StringColumn } from '@servicenow/sdk/core'
import { FlowObject, Subflow, wfa } from '@servicenow/sdk/automation'

/**
 * Test subflow for assignSubflowOutputs with FlowObject
 * Tests that plain object literals can be assigned to FlowObject outputs
 */
export const assignSubflowOutputsFlowObjectTest = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-flow-object-test'],
        name: 'AssignSubflowOutputs FlowObject Test',
        description: 'Test assignSubflowOutputs with FlowObject values',
        inputs: {
            inputName: StringColumn({ label: 'Input Name', mandatory: false }),
            inputAge: IntegerColumn({ label: 'Input Age', mandatory: false }),
        },
        outputs: {
            // Simple FlowObject with primitive fields
            userInfo: FlowObject({
                fields: {
                    name: StringColumn({ label: 'Name', mandatory: false }),
                    age: IntegerColumn({ label: 'Age', mandatory: false }),
                    isActive: BooleanColumn({ label: 'Is Active', mandatory: false }),
                },
                label: 'User Info',
                mandatory: false,
            }),

            // FlowObject with mixed field types
            settings: FlowObject({
                fields: {
                    theme: StringColumn({ label: 'Theme', mandatory: false }),
                    fontSize: IntegerColumn({ label: 'Font Size', mandatory: false }),
                    enabled: BooleanColumn({ label: 'Enabled', mandatory: false }),
                },
                label: 'Settings',
                mandatory: false,
            }),

            // Nested FlowObject
            config: FlowObject({
                fields: {
                    database: FlowObject({
                        fields: {
                            host: StringColumn({ label: 'Host', mandatory: false }),
                            port: IntegerColumn({ label: 'Port', mandatory: false }),
                        },
                        label: 'Database',
                        mandatory: false,
                    }),
                },
                label: 'Config',
                mandatory: false,
            }),
        },
    },
    (params) => {
        // Test 1: Simple FlowObject with plain object literal
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-simple-object'],
                annotation: 'Simple FlowObject with literals',
            },
            params.outputs,
            {
                userInfo: {
                    name: 'Jane Smith',
                    age: 28,
                    isActive: true,
                },
            }
        )

        // Test 2: FlowObject with datapills
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-object-datapills'],
                annotation: 'FlowObject with datapills',
            },
            params.outputs,
            {
                userInfo: {
                    name: wfa.dataPill(params.inputs.inputName, 'string'),
                    age: wfa.dataPill(params.inputs.inputAge, 'integer'),
                    isActive: false,
                },
            }
        )

        // Test 3: FlowObject with mixed literals and datapills
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-mixed-values'],
                annotation: 'Mixed literals and datapills',
            },
            params.outputs,
            {
                settings: {
                    theme: wfa.dataPill(params.inputs.inputName, 'string'),
                    fontSize: 14,
                    enabled: true,
                },
            }
        )

        // Test 4: Nested FlowObject
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-nested-object'],
                annotation: 'Nested FlowObject',
            },
            params.outputs,
            {
                config: {
                    database: {
                        host: 'prod-db.example.com',
                        port: 3306,
                    },
                },
            }
        )
    }
)
